function respond(int $status,array $data):never {http_response_code($status);echo json_encode($data);exit;}
function escPdf(string $s):string {return str_replace(["\\","(",")","\r","\n"],["\\\\","\\(","\\)",""," "],iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',$s)?:'');}
function makePdf(array $d):string {
 $pages=[];$ops=[];$y=0;
 $newPage=function()use(&$pages,&$ops,&$y){if($ops)$pages[]=implode("\n",$ops);$ops=['0.025 0.075 0.09 rg 0 0 595 842 re f','0.13 0.87 0.80 rg 0 811 595 31 re f','0.02 0.09 0.10 rg 0 807 595 3 re f'];$y=778;};
 $text=function(string $t,int $size=11,bool $bold=false,string $color='0.89 0.96 0.96')use(&$ops,&$y,$newPage){if($y<66)$newPage();$ops[]=$color.' rg BT /'.($bold?'F2':'F1').' '.$size.' Tf 46 '.$y.' Td ('.escPdf($t).') Tj ET';$y-=($size+10);};
 $wrap=function(string $t,int $size=11,bool $bold=false)use($text){$t=preg_replace('/\s+/u',' ',trim($t));$words=explode(' ',$t);$line='';$max=$size>=17?45:($size>=13?66:86);foreach($words as $w){if(strlen($line.' '.$w)>$max&&$line!==''){$text($line,$size,$bold);$line=$w;}else $line=trim($line.' '.$w);}if($line!=='')$text($line,$size,$bold);};
 $newPage();$text('SHIPWREKT  /  WHITE HATS. BLACK FLAGS.',16,true,'0.12 0.9 0.82');$y-=12;
 $wrap('WEBSITE ASSESSMENT',23,true);$wrap((string)($d['target']??$d['repository']??'Assessment'),14,true);
 $text('Issued: '.gmdate('Y-m-d H:i').' UTC',10);$text('Product: '.(string)($d['product']??'The Lookout'),10);$y-=18;
 $findings=array_slice(is_array($d['findings']??null)?$d['findings']:[],0,75);
 $text('EXECUTIVE SUMMARY',16,true,'0.12 0.9 0.82');
 $wrap(count($findings).' observations recorded in the defined assessment scope. Findings are configuration and visibility signals, not proof of compromise.');
 $counts=[];foreach($findings as $f){$sev=strtoupper((string)($f['severity']??'INFO'));$counts[$sev]=($counts[$sev]??0)+1;}
 $text('Severity distribution: '.implode('  |  ',array_map(fn($k,$v)=>$k.': '.$v,array_keys($counts),$counts)),10);$y-=16;
 $text('FINDINGS & RECOMMENDATIONS',16,true,'0.12 0.9 0.82');
 foreach($findings as $i=>$f){if($y<165)$newPage();$wrap(sprintf('%02d  [%s]  %s',$i+1,strtoupper((string)($f['severity']??'info')),(string)($f['title']??'Observation')),12,true);$wrap('Evidence: '.(string)($f['evidence']??''),10);$wrap('Recommended action: '.(string)($f['recommendation']??''),10);$y-=11;}
 if($y<180)$newPage();$text('SCOPE & LIMITATIONS',16,true,'0.12 0.9 0.82');
 foreach(($d['limitations']??['Automated observations only.']) as $l)$wrap('• '.(string)$l,10);
 $wrap('Generated by SHIPWREKT. This report does not certify security, demonstrate exploitation or replace a penetration test.',10);
 $pages[]=implode("\n",$ops);
 $objs=[null];$add=function(string $v)use(&$objs){$objs[]=$v;return count($objs)-1;};
 $font1=$add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');$font2=$add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
 $catalog=$add('');$root=$add('');$pageIds=[];
 foreach($pages as $content){$stream=$add('<< /Length '.strlen($content)." >>\nstream\n".$content."\nendstream");$pageIds[]=$add('<< /Type /Page /Parent '.$root.' 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 '.$font1.' 0 R /F2 '.$font2.' 0 R >> >> /Contents '.$stream.' 0 R >>');}
 $objs[$root]='<< /Type /Pages /Count '.count($pageIds).' /Kids ['.implode(' ',array_map(fn($i)=>$i.' 0 R',$pageIds)).'] >>';
 $objs[$catalog]='<< /Type /Catalog /Pages '.$root.' 0 R >>';
 $pdf="%PDF-1.4\n";$offset=[0];for($i=1;$i<count($objs);$i++){$offset[$i]=strlen($pdf);$pdf.=$i." 0 obj\n".$objs[$i]."\nendobj\n";}
 $xref=strlen($pdf);$pdf.="xref\n0 ".count($objs)."\n0000000000 65535 f \n";for($i=1;$i<count($objs);$i++)$pdf.=sprintf('%010d 00000 n ',$offset[$i])."\n";
 return $pdf."trailer\n<< /Size ".count($objs)." /Root ".$catalog." 0 R >>\nstartxref\n".$xref."\n%%EOF";
}
function mailReport(string $email,array $d):bool {
 $pdf=makePdf($d);$boundary='shipwrekt_'.bin2hex(random_bytes(12));
 $subject='Your SHIPWREKT website assessment report';
 $plain="Your SHIPWREKT report is attached as a PDF.\n\nScope and limitations are described inside.\n\nSHIPWREKT | White Hats. Black Flags.\nhttps://toasty.media/shipwrekt/";
 $mime="MIME-Version: 1.0\r\nFrom: SHIPWREKT via Toasty Media <hello@toasty.media>\r\nContent-Type: multipart/mixed; boundary=\"".$boundary."\"\r\n";
 $body="--".$boundary."\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n".$plain."\r\n";
 $body.="--".$boundary."\r\nContent-Type: application/pdf; name=\"SHIPWREKT-Assessment.pdf\"\r\nContent-Disposition: attachment; filename=\"SHIPWREKT-Assessment.pdf\"\r\nContent-Transfer-Encoding: base64\r\n\r\n".chunk_split(base64_encode($pdf))."\r\n--".$boundary."--\r\n";
 return mail($email,$subject,$body,$mime,'-fhello@toasty.media');
}
$config='/home/fmxgijyvpq/.shipwrekt/report-config.php';
if(is_file($config)){require_once $config;}
$dir=getenv('SHIPWREKT_REPORT_STORE');$secret=getenv('SHIPWREKT_REPORT_SECRET');
if(!$dir||!str_starts_with($dir,'/')||!is_dir($dir)||!is_writable($dir)||str_contains($dir,'public_html')||str_contains($dir,'htdocs')||!$secret||strlen($secret)<32)respond(503,['error'=>'Email delivery is not configured.']);
if($_SERVER['REQUEST_METHOD']==='GET'){
 $token=(string)($_GET['confirm']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$token))respond(400,['error'=>'Invalid confirmation link.']);
 $file=$dir.'/'.hash_hmac('sha256',$token,$secret).'.json';
 if(!is_file($file))respond(410,['error'=>'This confirmation link has expired or already been used.']);
 $raw=file_get_contents($file);$record=json_decode($raw?:'',true);
 if(!is_array($record)||($record['expires']??0)<time()){unlink($file);respond(410,['error'=>'Confirmation expired.']);}
 if(!mailReport($record['email'],$record['report']))respond(502,['error'=>'Email delivery failed. Contact the crew.']);
 unlink($file);header('Content-Type: text/html; charset=utf-8');echo '<!doctype html><title>SHIPWREKT</title><body style="background:#061417;color:#35e6d3;font:20px system-ui;padding:12vw"><h1>Report dispatched.</h1><p>Check your inbox for your SHIPWREKT PDF assessment.</p><a style="color:#fff" href="/shipwrekt/">Back to SHIPWREKT</a></body>';exit;
}
if($_SERVER['REQUEST_METHOD']!=='POST')respond(405,['error'=>'POST required.']);
if((int)($_SERVER['CONTENT_LENGTH']??0)>150000)respond(413,['error'=>'Report too large.']);
$input=json_decode(file_get_contents('php://input'),true);if(!is_array($input))respond(400,['error'=>'Invalid request.']);
$email=strtolower(trim((string)($input['email']??'')));$d=$input['report']??null;
if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254||!is_array($d)||empty($d['ok'])||!is_array($d['findings']??null)||count($d['findings'])>100)respond(400,['error'=>'Valid email and assessment required.']);
$signature=(string)($d['report_signature']??'');unset($d['report_signature']);
$expected=hash_hmac('sha256',json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$secret);
if(!preg_match('/^[a-f0-9]{64}$/D',$signature)||!hash_equals($expected,$signature))respond(403,['error'=>'Only genuine SHIPWREKT assessments can be emailed.']);
$issued=strtotime((string)($d['checked_at']??''));if(!$issued||abs(time()-$issued)>1800)respond(400,['error'=>'Assessment expired. Please scan again.']);
$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');$limit=$dir.'/rate-'.hash_hmac('sha256',$ip,$secret);
$events=json_decode(@file_get_contents($limit)?:'[]',true);$events=is_array($events)?array_filter($events,fn($t)=>is_int($t)&&$t>time()-3600):[];
if(count($events)>=5)respond(429,['error'=>'Hourly email limit reached.']);$events[]=time();file_put_contents($limit,json_encode(array_values($events)),LOCK_EX);
$token=bin2hex(random_bytes(32));$file=$dir.'/'.hash_hmac('sha256',$token,$secret).'.json';
file_put_contents($file,json_encode(['email'=>$email,'report'=>$d,'expires'=>time()+1800]),LOCK_EX);chmod($file,0600);
$link='https://toasty.media/shipwrekt/api/email-report.php?confirm='.$token;
